package dev.veltraph.client.navigation;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
class LegacyParentCleanupUsabilityIdentityTest {
 LegacyParentCleanupUsabilityIdentity.Evidence scene(boolean playerWorld,boolean alive,boolean lava,boolean passenger){return new LegacyParentCleanupUsabilityIdentity.Evidence(true,playerWorld,alive,lava,passenger,false,false,true,false,true,true,true,true,true,true,true);}
 LegacyCleanupTransactionIdentity.Issuer ready(){var c=new Object();var h=new Object();var p=new Object();var i=new Object();var issuer=LegacyCleanupTransactionIdentity.Issuer.capture(c,h,p,1,100);assertTrue(issuer.keys(new Object(),9,true));assertTrue(issuer.camera(new Object(),true,true));assertTrue(issuer.beginInventory(p,h,2,true));assertTrue(issuer.inventory(i,p,h));assertTrue(issuer.complete(i,new Object(),p,c,3,true,true));return issuer;}
 @Test void latePassengerMutationRefusesWithoutConsumingThenFreshSceneCanConsumeOnce(){var issuer=ready();boolean[] passenger={false};assertTrue(LegacyParentCleanupUsabilityIdentity.usable(scene(true,true,false,passenger[0])));long generation=5,epoch=8,serial=4;Runnable lateRoleOrClock=()->passenger[0]=true;lateRoleOrClock.run();assertFalse(issuer.consume(4,true,LegacyParentCleanupUsabilityIdentity.usable(scene(true,true,false,passenger[0]))));assertFalse(issuer.consumed());assertEquals(5,generation);assertEquals(8,epoch);assertEquals(4,serial);passenger[0]=false;assertTrue(issuer.consume(4,true,LegacyParentCleanupUsabilityIdentity.usable(scene(true,true,false,passenger[0]))));assertFalse(issuer.consume(4,true,true));}
 @Test void lateLavaMutationCannotConsume(){var issuer=ready();assertFalse(issuer.consume(4,true,LegacyParentCleanupUsabilityIdentity.usable(scene(true,true,true,false))));assertFalse(issuer.consumed());}
 @Test void samePwcReferencesWithDifferentPlayerLevelCannotConsume(){var issuer=ready();assertFalse(issuer.consume(4,true,LegacyParentCleanupUsabilityIdentity.usable(scene(false,true,false,false))));assertFalse(issuer.consumed());}
 @Test void lateDeathCannotConsume(){var issuer=ready();assertFalse(issuer.consume(4,true,LegacyParentCleanupUsabilityIdentity.usable(scene(true,false,false,false))));assertFalse(issuer.consumed());}
 @Test void everyRemainingNativeEligibilityFieldIsRequired(){var valid=scene(true,true,false,false);assertTrue(LegacyParentCleanupUsabilityIdentity.usable(valid));assertFalse(LegacyParentCleanupUsabilityIdentity.usable(null));boolean[] f={true,true,true,false,false,false,false,true,false,true,true,true,true,true,true,true};for(int i=0;i<f.length;i++){var a=f.clone();a[i]=!a[i];var e=new LegacyParentCleanupUsabilityIdentity.Evidence(a[0],a[1],a[2],a[3],a[4],a[5],a[6],a[7],a[8],a[9],a[10],a[11],a[12],a[13],a[14],a[15]);assertFalse(LegacyParentCleanupUsabilityIdentity.usable(e),"native field "+i);var issuer=ready();assertFalse(issuer.consume(4,true,LegacyParentCleanupUsabilityIdentity.usable(e)));assertFalse(issuer.consumed());}}
}
